62	export function buildPosAqPipeline(
63	    tipoCreditorio: string,
64	    ordemExpedicao: string,
65	    finalidade: string,
66	): IEtapa[] {
67	    let stages: IEtapa[];
68	    if (finalidade === 'compensacao') {
69	        stages = posAqEtapasCompensacao;
70	    } else if (tipoCreditorio !== 'creditorio') {
71	        stages = posAquisicaoEtapas;
72	    } else if (ordemExpedicao === 'exp_antes') {
73	        stages = [posAqEtapasExtra[0], posAqEtapasExtra[1], ...posAquisicaoEtapas];
74	    } else {
75	        stages = [
76	            posAquisicaoEtapas[0],
77	            posAqEtapasExtra[0],
78	            posAqEtapasExtra[1],
79	            posAquisicaoEtapas[2],
80	            posAquisicaoEtapas[3],
81	            posAquisicaoEtapas[4],
82	        ];
83	    }
84	
85	    // Creditório: paleta Figma (roxo → índigo → verde).
86	    if (tipoCreditorio === 'creditorio' && finalidade !== 'compensacao') {
87	        return stages.map((etapa) => ({
88	            ...etapa,
89	            color: CREDITORIO_ETAPA_COLORS[etapa.id] ?? etapa.color,
90	        }));
91	    }
92	
93	    // Precatório / Investimento: paleta Figma própria (distinta do Creditório).
94	    if (tipoCreditorio !== 'creditorio' && finalidade !== 'compensacao') {
95	        return stages.map((etapa) => ({
96	            ...etapa,
97	            color: PRECATORIO_ETAPA_COLORS[etapa.id] ?? etapa.color,
98	        }));
99	    }
100	
101	    return stages;
102	}
