158	export function fmtTaskDate(d: string): { text: string; color: string; label: string } {
159	    const dt = new Date(d + 'T00:00:00');
160	    const now = new Date();
161	    const diff = Math.round((dt.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
162	    const formatted = dt.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
163	    if (diff < 0)
164	        return { text: formatted, color: '#dc2626', label: `${Math.abs(diff)}d atrasada` };
165	    if (diff <= 3) return { text: formatted, color: '#d97706', label: `${diff}d restantes` };
166	    return { text: formatted, color: '#888', label: `${diff}d` };
167	}
