466	export function buildDashEsferaLoa(items: IPosAquisicaoItem[]) {
467	    const pa = items.filter((i) => i.statusDue === 'pos_aquisicao');
468	    const esferaMap: Record<string, string> = {
469	        Federal: 'FEDERAL',
470	        Estadual: 'ESTADUAL',
471	        Municipal: 'MUNICIPAL',
472	    };
473	    const esferaColors: Record<string, string> = {
474	        FEDERAL: '#2563eb',
475	        ESTADUAL: '#0891b2',
476	        MUNICIPAL: '#7c3aed',
477	    };
478	
479	    const result: Record<
480	        string,
481	        {
482	            color: string;
483	            qtd: number;
484	            valor: number;
485	            loas: Record<string, { qtd: number; valor: number }>;
486	            subs: Record<string, { qtd: number; valor: number }>;
487	        }
488	    > = {};
489	
490	    pa.forEach((i) => {
491	        const esf = esferaMap[i.esfera] || 'FEDERAL';
492	        if (!result[esf])
493	            result[esf] = { color: esferaColors[esf], qtd: 0, valor: 0, loas: {}, subs: {} };
494	        result[esf].qtd++;
495	        result[esf].valor += i.valorLiquido;
496	        const loa = String(i.loa);
497	        if (!result[esf].loas[loa]) result[esf].loas[loa] = { qtd: 0, valor: 0 };
498	        result[esf].loas[loa].qtd++;
499	        result[esf].loas[loa].valor += i.valorLiquido;
500	        if (esf === 'FEDERAL') {
501	            const key = i.enteDevedor;
502	            if (!result[esf].subs[key]) result[esf].subs[key] = { qtd: 0, valor: 0 };
503	            result[esf].subs[key].qtd++;
504	            result[esf].subs[key].valor += i.valorLiquido;
505	        } else {
506	            const stateMatch = i.enteDevedor.match(/(?:de\s+|do\s+)(.+)$/);
507	            const key = stateMatch ? stateMatch[1] : i.esfera;
508	            if (!result[esf].subs[key]) result[esf].subs[key] = { qtd: 0, valor: 0 };
509	            result[esf].subs[key].qtd++;
510	            result[esf].subs[key].valor += i.valorLiquido;
511	        }
512	    });
513	    const totalValor = pa.reduce((s, i) => s + i.valorLiquido, 0);
514	    const allSubs: {
515	        nome: string;
516	        qtd: number;
517	        valor: number;
518	        esf: string;
519	        color: string;
520	    }[] = [];
521	    Object.entries(result).forEach(([esf, d]) => {
522	        Object.entries(d.subs).forEach(([nome, s]) =>
523	            allSubs.push({ nome, ...s, esf, color: d.color }),
524	        );
525	    });
526	    allSubs.sort((a, b) => b.valor - a.valor);
527	    return { data: result, total: pa.length, totalValor, allSubs };
528	}
