import type { OficioFormStep1Result } from '@/app/crm/broker/_components/OficioForm';
import { CalculatorEnum } from '@/enums/calculator.enum';
import { mapDeducoesFromApi } from '@/functions/calcform/applyCalculadoraPayloadToForm';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import type { Cedente, GetPostPurchaseByIdResponse } from '@/interfaces/IPosAquisicao';
import type { CvldFormInputsProps } from '@/types/cvldform';
import type { DetailedOficioProps } from '@/types/oficio';
import type { Step2Values, Step3Values, Step4Values } from './steps/schemas';
import type { WizardInitialData } from './WizardContext';
import { toBRLInput } from '../utils';
import { apiDateToBR } from './wizard-dates';
import { TIPOS_CUSTO_PADRAO } from './steps/constants';

function normalizeTipoDoOficio(value?: string | null): string {
    const normalized = String(value ?? '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .trim()
        .toUpperCase();

    if (normalized === 'PRECATORIO') return 'PRECATÓRIO';
    if (normalized === 'CREDITORIO') return 'CREDITÓRIO';
    return String(value ?? '');
}

function toPtBrMoneyInput(value?: number | string | null): string {
    if (value === null || value === undefined || value === '') return '';
    return formatCurrency(value).replace(/^R\$\s?/, '');
}

function mapFinalidade(value?: string | null): 'Investimento' | 'Compensação' {
    return String(value ?? '').toLowerCase() === 'compensacao' ? 'Compensação' : 'Investimento';
}

function mapStatusInvestimento(value?: string | null): string {
    const normalized = String(value ?? '').toLowerCase();
    if (normalized.includes('terceiro')) return 'Terceiro';
    if (normalized.includes('pago')) return 'Pago';
    return 'Em Carteira';
}

function mapStep1(detail: GetPostPurchaseByIdResponse): OficioFormStep1Result | null {
    const richDetail = detail as GetPostPurchaseByIdResponse & {
        data_base?: string | null;
        data_requisicao?: string | null;
        proposta_escolhida?: string | number | null;
        comissao_escolhida?: string | number | null;
    };
    const due = detail.due_diligence as
        | {
              extrato_detail?: {
                  id?: string;
                  valor_principal?: string | number;
                  data_base?: string;
                  data_requisicao?: string;
                  LOA?: number;
                  tribunal?: string;
                  tipo_do_oficio?: string;
                  esfera?: string;
                  regime?: string;

/**
 * Formatadores das telas de Operações.
 *
 * `BRL` reaproveita `formatCurrency` e as datas usam `dateFormater`, ambos de
 * `@/functions/formaters`. Os demais ficam aqui porque o equivalente do repo
 * entrega outro formato: `formatCompactCurrency` usa sufixo `M`/`k` em vez do
 * `mi`/`mil` pt-BR, e `formatNumberToPercentage` tem
 * `maximumSignificantDigits: 4`, que anula o `minimumFractionDigits: 2` e faz
 * "12,50%" sair como "12,5%" — o que quebra o alinhamento das colunas
 * `tabular-nums` destas telas.
 */

import { formatCurrency } from '@/functions/formaters/formatCurrency';

/** R$ 1.234,56 */
export const BRL = (n: number): string => formatCurrency(n);

/** R$ 1.235 — sem centavos, para tabelas densas. */
export const BRLc = (n: number): string =>
    'R$ ' + n.toLocaleString('pt-BR', { maximumFractionDigits: 0 });

/**
 * R$ 1,85 mi · R$ 890 mil · R$ 640 — versão curta para rankings e degraus,
 * onde o valor cheio estoura a coluna. `formatCompactCurrency` do repo não
 * serve aqui: usa sufixo `M`/`k` e ponto decimal, fora do padrão pt-BR.
 */
export const BRLcompacto = (n: number): string => {
    const abs = Math.abs(n);
    if (abs >= 1e6) {
        return (
            'R$ ' +
            (n / 1e6).toLocaleString('pt-BR', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2,
            }) +
            ' mi'
        );
    }
    if (abs >= 1e3) {
        return 'R$ ' + (n / 1e3).toLocaleString('pt-BR', { maximumFractionDigits: 0 }) + ' mil';
    }
    return BRLc(n);
};

/** R$ 5,6 mi */
export const MI = (n: number): string =>
    'R$ ' +
    (n / 1e6).toLocaleString('pt-BR', {
        minimumFractionDigits: 1,
        maximumFractionDigits: 1,
    }) +
    ' mi';

/** 5,6 mi — sem o prefixo, para eixos de gráfico. */
export const MIc = (n: number): string =>
    (n / 1e6).toLocaleString('pt-BR', {
        minimumFractionDigits: 1,
        maximumFractionDigits: 1,
    }) + ' mi';

/** Recebe o percentual já em base 100: `PCT(12.5)` → "12,50%". */
export const PCT = (n: number): string =>
    (Number.isFinite(n) ? n : 0).toLocaleString('pt-BR', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    }) + '%';

