'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import {
    AlertTriangle,
    ArrowLeft,
    Check,
    Copy,
    FileText,
    Link2,
    MessageSquare,
    PencilLine,
    Scale,
    Users,
} from 'lucide-react';
import { getInitials } from '@/functions/formaters/getInitials';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import type { IPosAquisicaoData, IPosAquisicaoItem, IProcesso } from '../../types';
import { formatCurrency, getEtapaById } from '../../utils';
import { Button } from '@/components/Button';
import { Tenants } from '@/enums/tenants.enum';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import { cn } from '@/lib/utils';
import { TruncatedText } from '@/components/ui/truncated-text';
import { PosAquisicaoDetailMobileOverflowMenu } from './PosAquisicaoDetailQuickActions';
import { PosAquisicaoIntegraLink } from './PosAquisicaoIntegraLink';
import { ImportadoBadge } from '@/components/PostAquisition/shared/ImportadoBadge';

const COPY_FEEDBACK_MS = 2000;

async function writeClipboard(text: string): Promise<boolean> {
    try {
        await navigator.clipboard.writeText(text);
        return true;
    } catch {
        sendToastMessage({
            title: 'Não foi possível copiar para a área de transferência.',
            type: 'error',
        });
        return false;
    }
}

interface IconCopyButtonProps {
    text: string;
    label: string;
    copiedLabel?: string;
    iconSize?: number;
    className?: string;
}

function IconCopyButton({
    text,
    label,
    copiedLabel = 'Copiado',
    iconSize = 12,
    className,
}: IconCopyButtonProps) {
    const [copied, setCopied] = useState(false);
    const resetTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        return () => {
            if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
        };
    }, []);

    async function handleCopy() {
        if (!text) return;
        const ok = await writeClipboard(text);
        if (!ok) return;

        setCopied(true);
        if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
        resetTimerRef.current = setTimeout(() => setCopied(false), COPY_FEEDBACK_MS);
    }

    return (
        <button
            type="button"
            onClick={() => void handleCopy()}
            disabled={!text}
            aria-live="polite"
            aria-label={copied ? copiedLabel : label}
            title={copied ? copiedLabel : label}
            className={cn(
                'inline-flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-md transition-colors duration-200',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-celer-blue/40',
                'disabled:cursor-not-allowed disabled:opacity-40',
                copied
                    ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400'
                    : 'text-muted-foreground/60 hover:bg-muted hover:text-foreground',
                className,
            )}
        >
            {copied ? (
                <Check size={iconSize} strokeWidth={2.5} aria-hidden />
            ) : (
                <Copy size={iconSize} aria-hidden />
            )}
        </button>
    );
}

/** Nome longo com clamp; clique expande/recolhe. */
function ExpandableName({ name }: { name: string }) {
    const [expanded, setExpanded] = useState(false);
    const [canToggle, setCanToggle] = useState(false);
    const ref = useRef<HTMLParagraphElement>(null);

    useEffect(() => {
        setExpanded(false);
        setCanToggle(false);
    }, [name]);

    useLayoutEffect(() => {
        if (expanded) return;
        const el = ref.current;
        if (!el) return;
        if (el.scrollHeight > el.clientHeight + 2) {
            setCanToggle(true);
        }
    }, [name, expanded]);

    return (
        <div className="min-w-0 flex-1">
            <button
                type="button"
                onClick={() => {
                    if (!canToggle && !expanded) return;
                    setExpanded((v) => !v);
                }}
                disabled={!canToggle && !expanded}
                aria-expanded={canToggle || expanded ? expanded : undefined}
                className={cn(
                    'w-full min-w-0 text-left',
                    (canToggle || expanded) &&
                        'cursor-pointer rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-celer-blue/40',
                    !canToggle && !expanded && 'cursor-default',
                )}
            >
                <p
                    ref={ref}
                    className={cn(
                        'text-xs font-semibold leading-snug text-foreground wrap-break-word',
                        !expanded && 'line-clamp-2',
                    )}
                >
                    {name}
                </p>
            </button>
            {(canToggle || expanded) && (
                <button
                    type="button"
                    onClick={() => setExpanded((v) => !v)}
                    className="mt-0.5 text-[10px] font-semibold text-celer-blue transition-colors hover:text-celer-blue/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-celer-blue/40"
                >
                    {expanded ? 'Ver menos' : 'Ver mais'}
                </button>
            )}
        </div>
    );
}

function formatPct(value: number): string {
    return (
        value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%'
    );
}

function getTipoShort(tipo: string): string {
    const map: Record<string, string> = {
        agravo: 'AGR',
        reclamacao_cnj: 'RCNJ',
        ms: 'MS',
        reclamacao_correg: 'RCOR',
        embargos: 'EMB',
        acao_autonoma: 'AA',
    };
    return map[tipo] ?? tipo.slice(0, 3).toUpperCase();
}

function getTipoNome(tipo: string): string {
    const map: Record<string, string> = {
        agravo: 'Agravo',
        reclamacao_cnj: 'Reclamação CNJ',
        ms: 'Mandado de Segurança',
        reclamacao_correg: 'Reclamação Corregedoria',
        embargos: 'Embargos de Declaração',
        acao_autonoma: 'Ação Autônoma',
    };
    return map[tipo] ?? tipo;
}

interface PosAquisicaoHeaderProps {
    item: IPosAquisicaoItem;
    pa: IPosAquisicaoData;
    emLitigio: boolean;
    /** Exibe botão Litígios entre Editar e o balão de mensagem quando há caso(s). */
    hasLitigioCases?: boolean;
    processosVinculados: IProcesso[];
    dueDiligenceId?: string | null;
    dueDiligenceModelo?: string | null;
    onViewProcesso: (id: string) => void;
    onLinkProcesso: () => void;
    onBack?: () => void;
    onEditAtivo?: () => void;
    /** MASTER-only: abre dialog irreversível pós → liquidação. */
    onReverterParaLiquidacao?: () => void;
    commentsCount?: number;
    onOpenComments?: () => void;
    onOpenLitigioHistory?: () => void;
}

/** Cores do header — tokens Celer (light/dark). */
const badgeNeutralClass =
    'inline-flex h-5 max-w-full shrink-0 items-center truncate rounded-full border border-celer-line bg-celer-panel px-2 text-[10px] font-semibold uppercase tracking-[0.02em] text-celer-muted sm:h-6 sm:px-2.5 sm:text-[11px] sm:tracking-[0.04em] dark:border-white/10 dark:bg-celer-slate/50 dark:text-muted-foreground';

const badgeLitigioClass =
    'inline-flex h-5 shrink-0 items-center gap-1 rounded-full border border-red-500 bg-celer-paper px-2 text-[10px] font-bold uppercase tracking-[0.02em] text-red-600 sm:h-6 sm:px-2.5 sm:text-[11px] sm:tracking-[0.04em] dark:border-red-500/70 dark:bg-transparent dark:text-red-400';

const iconBtnClass =
    'flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-xl border border-celer-line/80 bg-celer-paper text-muted-foreground shadow-sm transition-colors hover:bg-muted/50 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-celer-blue/40 dark:border-white/10 dark:bg-celer-graphite dark:hover:bg-celer-slate/60';

const actionBtnClass =
    'flex h-9 shrink-0 cursor-pointer items-center justify-center gap-1.5 rounded-xl border border-celer-line/80 bg-celer-paper px-2.5 text-xs font-semibold text-foreground transition-colors hover:bg-muted/50 sm:h-8 sm:px-3 sm:py-1.5 dark:border-white/10 dark:bg-celer-graphite dark:hover:bg-celer-slate/60';

/** Cap visual do badge de comentários (exibe `9+` acima disso). */
const COMMENTS_BADGE_DISPLAY_CAP = 9;

function formatCommentsBadge(count: number): string {
    return count > COMMENTS_BADGE_DISPLAY_CAP
        ? `${COMMENTS_BADGE_DISPLAY_CAP}+`
        : String(count);
}

export function PosAquisicaoHeader({
    item,
    pa,
    emLitigio,
    hasLitigioCases = false,
    processosVinculados,
    dueDiligenceId = null,
    dueDiligenceModelo = null,
    onViewProcesso,
    onLinkProcesso,
    onBack,
    onEditAtivo,
    onReverterParaLiquidacao,
    commentsCount = 0,
    onOpenComments,
    onOpenLitigioHistory,
}: PosAquisicaoHeaderProps) {
    const isFromDasi = getTenantFromUrl() === Tenants.DASI;
    const showEdit = Boolean(onEditAtivo && !isFromDasi);
    const showIntegraLink = !isFromDasi;
    const showLitigioAction = Boolean(
        (hasLitigioCases || emLitigio) && onOpenLitigioHistory,
    );

    return (
        <header className="flex h-full min-h-0 flex-col rounded-2xl border border-celer-line/80 bg-celer-paper shadow-sm dark:border-white/10 dark:bg-celer-graphite">
            <div className="flex flex-col gap-3 px-3 pb-3 pt-3 sm:gap-4 sm:px-4 sm:pb-4 sm:pt-4">
                {/* Toolbar: ← | CPF/ente | ⋮ mobile | Editar | Litígios? | 💬 */}
                <div className="flex items-center gap-2.5">
                    <div className="flex min-w-0 flex-1 items-center gap-2">
                        {onBack ? (
                            <button
                                type="button"
                                onClick={onBack}
                                className={iconBtnClass}
                                aria-label="Voltar"
                            >
                                <ArrowLeft size={16} aria-hidden />
                            </button>
                        ) : null}
                        <p className="min-w-0 flex-1 self-center wrap-break-word font-mono text-[11px] font-medium uppercase leading-snug tracking-[0.02em] text-celer-muted dark:text-muted-foreground">
                            {item.cpfCnpj} · {item.enteDevedor}
                        </p>
                    </div>
                    {onOpenComments && onOpenLitigioHistory ? (
                        <PosAquisicaoDetailMobileOverflowMenu
                            commentsCount={commentsCount}
                            onOpenComments={onOpenComments}
                            onOpenLitigioHistory={onOpenLitigioHistory}
                            onEditAtivo={onEditAtivo}
                            dueDiligenceId={dueDiligenceId}
                            dueDiligenceModelo={dueDiligenceModelo}
                            onReverterParaLiquidacao={onReverterParaLiquidacao}
                            className="shrink-0"
                        />
                    ) : null}
                    {showIntegraLink ? (
                        <PosAquisicaoIntegraLink
                            dueDiligenceId={dueDiligenceId}
                            dueDiligenceModelo={dueDiligenceModelo}
                            className="hidden shrink-0 sm:inline-flex"
                        />
                    ) : null}
                    {showEdit && (
                        <Button
                            type="button"
                            onClick={onEditAtivo}
                            className={cn(actionBtnClass, 'hidden shrink-0 sm:inline-flex')}
                            aria-label="Editar"
                        >
                            <PencilLine size={14} />
                            <span>Editar</span>
                        </Button>
                    )}
                    {showLitigioAction ? (
                        <Button
                            type="button"
                            onClick={onOpenLitigioHistory}
                            className={cn(actionBtnClass, 'hidden shrink-0 sm:inline-flex')}
                            aria-label="Litígios"
                        >
                            <Scale size={14} aria-hidden />
                            <span>Litígios</span>
                        </Button>
                    ) : null}
                    {onOpenComments ? (
                        <div className="relative hidden shrink-0 sm:block">
                            <button
                                type="button"
                                onClick={onOpenComments}
                                className={iconBtnClass}
                                aria-label="Comentários"
                            >
                                <MessageSquare size={15} aria-hidden />
                            </button>
                            {commentsCount > 0 ? (
                                <span className="absolute -right-1 -top-1 flex size-4 items-center justify-center rounded-full bg-celer-blue text-[10px] font-bold text-white">
                                    {formatCommentsBadge(commentsCount)}
                                </span>
                            ) : null}
                        </div>
                    ) : null}
                </div>

                {/* Nome — largura total do card, sem truncate (sempre legível) */}
                <h1
                    className="font-satoshi w-full max-w-full wrap-break-word text-[15px] font-bold uppercase leading-snug tracking-[-0.02em] text-celer-strong sm:text-lg md:text-xl dark:text-foreground"
                >
                    {item.nomeCredor}
                </h1>

                {/* Valor + badges (sempre empilhados) */}
                <div className="flex min-w-0 flex-col gap-4">
                    <p className="font-satoshi text-[22px] font-semibold leading-none tracking-normal text-celer-blue tabular-nums sm:text-[24px]">
                        {formatCurrency(item.valorLiquido)}
                    </p>
                    <div className="flex flex-row flex-wrap items-center gap-1.5">
                        <TruncatedText text={item.tipo} className={badgeNeutralClass} />
                        <span className={badgeNeutralClass}>
                            {pa.finalidade === 'investimento' ? 'INVESTIMENTO' : 'COMPENSAÇÃO'}
                        </span>
                        {emLitigio && (
                            <span className={badgeLitigioClass}>
                                <Scale size={11} strokeWidth={2.25} aria-hidden />
                                EM LITÍGIO
                            </span>
                        )}
                        <ImportadoBadge
                            importado={!!pa.importado}
                            variant="header"
                        />
                    </div>
                </div>
            </div>

            {/* Row 2: cards NPU */}
            <div className="grid grid-cols-1 gap-2.5 px-3 pb-3 sm:grid-cols-2 sm:gap-3 sm:px-4 sm:pb-4">
                {/* Processo Originário */}
                <div className="flex min-w-0 flex-col gap-2 rounded-xl border border-celer-line/60 bg-celer-panel/60 p-3 dark:border-white/10 dark:bg-celer-slate/30">
                    <div className="flex items-center justify-between gap-2">
                        <div className="flex min-w-0 items-center gap-1.5">
                            <FileText size={11} className="shrink-0 text-muted-foreground" />
                            <span className="truncate text-[10px] font-bold uppercase tracking-[0.12em] text-muted-foreground">
                                Processo Originário
                            </span>
                        </div>
                        <IconCopyButton
                            text={item.npuOriginario}
                            label="Copiar NPU originário"
                            copiedLabel="NPU originário copiado"
                        />
                    </div>
                    <p className="break-all font-mono text-[13px] font-bold leading-snug text-celer-blue sm:text-sm">
                        {item.npuOriginario}
                    </p>
                    {item.varaOrigem ? (
                        <p className="wrap-break-word text-[11px] leading-snug text-muted-foreground">
                            {item.varaOrigem}
                        </p>
                    ) : null}
                </div>

                {/* Precatório / Requisitório */}
                <div className="flex min-w-0 flex-col gap-2 rounded-xl border border-celer-line/60 bg-celer-panel/60 p-3 dark:border-white/10 dark:bg-celer-slate/30">

                                        )}
                                        <TruncatedText
                                            text={proc.npu || 'Sem NPU'}
                                            className="min-w-0 max-w-full truncate font-mono text-sm font-semibold text-foreground"
                                        />
                                    </div>
                                    <div className="flex min-w-0 flex-col gap-0.5 text-xs text-muted-foreground sm:flex-row sm:flex-wrap sm:items-center sm:gap-1.5">
                                        <span className="font-medium text-foreground">
                                            {getTipoNome(proc.tipo)}
                                        </span>
                                        {proc.tribunal && (
                                            <span className="hidden text-muted-foreground/40 sm:inline" aria-hidden>
                                                ·
                                            </span>
                                        )}
                                        {proc.tribunal && <span className="shrink-0">{proc.tribunal}</span>}
                                        {proc.vara && (
                                            <>
                                                <span className="hidden text-muted-foreground/40 sm:inline" aria-hidden>
                                                    ·
                                                </span>
                                                <TruncatedText
                                                    text={proc.vara}
                                                    className="min-w-0 max-w-full truncate sm:max-w-[220px]"
                                                />
                                            </>
                                        )}
                                        {proc.valorCausa ? (
                                            <>
                                                <span className="hidden text-muted-foreground/40 sm:inline" aria-hidden>
                                                    ·
                                                </span>
                                                <span className="font-mono font-bold text-foreground">
                                                    {formatCurrency(proc.valorCausa)}
                                                </span>
                                            </>
                                        ) : null}
                                    </div>
                                </div>
                                <div className="flex items-center justify-between gap-2 border-t border-border/40 pt-2.5 sm:shrink-0 sm:flex-col sm:items-end sm:justify-center sm:border-0 sm:pt-0">
                                    <span className="rounded-full border border-celer-line/60 bg-celer-paper px-2.5 py-0.5 text-[10px] font-bold tracking-wide text-muted-foreground dark:border-white/10 dark:bg-celer-slate/50 dark:text-foreground">
                                        {proc.etapaAtual || 'Registro'}
                                    </span>
                                    <button
                                        type="button"
                                        onClick={() => onViewProcesso(proc.id)}
                                        className={cn(
                                            actionBtnClass,
                                            'flex-none shadow-none sm:w-auto',
                                        )}
                                    >
                                        <span className="sm:hidden">Ver</span>
                                        <span className="hidden sm:inline">Ver Processo</span>
                                        <span className="text-muted-foreground/60">↗</span>
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {!isFromDasi && (
                    <div className="mt-2.5 flex sm:justify-center">
                        <button
                            type="button"
                            onClick={onLinkProcesso}
                            className="flex w-full cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-celer-line bg-celer-paper px-3 py-2 text-xs font-semibold text-muted-foreground transition-colors hover:border-muted-foreground/40 hover:bg-muted/30 hover:text-foreground sm:w-auto sm:py-1.5 dark:border-white/10 dark:bg-celer-graphite dark:hover:bg-celer-slate/50"
                        >
                            <Link2 size={13} />
                            Vincular novo processo
                        </button>
                    </div>
                )}
            </div>

            {/* Litígio alert */}
            {/* Litígio alert — Figma: fundo branco + vermelho mais saturado */}
            {emLitigio && (
                <div className="mx-3 mb-3 flex items-start gap-2.5 rounded-lg border border-red-400/80 bg-celer-paper px-4 py-3 dark:border-red-500/50 dark:bg-red-950/20 sm:mx-4">
                    <AlertTriangle
                        size={16}
                        className="mt-0.5 shrink-0 text-red-600 dark:text-red-400"
                        aria-hidden
                    />
                    <div className="min-w-0">
                        <p className="text-xs font-bold uppercase leading-tight tracking-[0.02em] text-red-600 dark:text-red-400">
                            LITÍGIO REGISTRADO
                        </p>
                        <p className="mt-0.5 text-[11px] leading-snug text-red-500 dark:text-red-400/90">
                            Este ativo possui litígio registrado na etapa{' '}
                            {getEtapaById(pa.litEtapaOrigem ?? pa.etapaAtual).nome}.
                        </p>
                    </div>
                </div>
            )}
        </header>
    );
}

